mapper.update:
UPDATE ticket_purchase_plan
SET session_id = #{sessionId},
    ticket_category_id = #{ticketCategoryId},
    quantity = #{quantity},
    status = 'DRAFT',
    active_plan_key = #{activePlanKey},
    completed_version = NULL,
    confirmed_at = NULL,
    completed_at = NULL,
    expire_time = (SELECT ps.sale_start_time FROM performance_session ps WHERE ps.id = #{sessionId}),
    version = version + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status IN ('DRAFT', 'READY')
  AND version = #{version}
  AND EXISTS (
      SELECT 1 FROM performance_session ps
      WHERE ps.id = #{sessionId}
        AND ps.sale_start_time IS NOT NULL
        AND ps.sale_start_time > #{now}
  )

UPDATE ticket_purchase_plan AS p
SET status = 'DRAFT',
    selected_audience_count = #{selectedAudienceCount},
    completed_version = NULL,
    confirmed_at = NULL,
    completed_at = NULL,
    version = version + 1,
    updated_at = #{updatedAt}
WHERE p.id = #{id}
  AND p.user_id = #{userId}
  AND p.status IN ('DRAFT', 'READY')
  AND p.version = #{version}
  AND p.session_id IS NOT NULL
  AND EXISTS (
      SELECT 1 FROM performance_session ps
      WHERE ps.id = p.session_id
        AND ps.sale_start_time IS NOT NULL
        AND ps.sale_start_time > #{now}
  )

UPDATE ticket_purchase_plan AS p
SET status = 'READY',
    version = version + 1,
    completed_version = #{completedVersion},
    confirmed_at = #{completedAt},
    completed_at = #{completedAt},
    updated_at = #{completedAt}
WHERE p.id = #{id}
  AND p.user_id = #{userId}
  AND p.status = 'DRAFT'
  AND p.version = #{version}
  AND EXISTS (
      SELECT 1 FROM performance_session ps
      WHERE ps.id = p.session_id
        AND ps.sale_start_time IS NOT NULL
        AND ps.sale_start_time > #{now}
  )

UPDATE ticket_purchase_plan AS p
SET status = #{status},
    version = version + 1,
    idempotency_token = #{idempotencyToken},
    order_request_id = #{orderRequestId},
    submitted_at = #{submittedAt},
    updated_at = #{updatedAt}
WHERE p.id = #{id}
  AND p.user_id = #{userId}
  AND p.status IN ('READY', 'FAILED')
  AND p.version = #{version}
  AND p.completed_version IS NOT NULL
  AND EXISTS (
      SELECT 1 FROM performance_session ps
      WHERE ps.id = p.session_id
        AND ps.sale_start_time IS NOT NULL
        AND ps.sale_start_time <= #{now}
        AND ps.sale_end_time IS NOT NULL
        AND ps.sale_end_time > #{now}
  )

UPDATE ticket_purchase_plan
SET status = #{status},
    order_request_id = #{orderRequestId},
    order_id = #{orderId},
    active_plan_key = NULL,
    version = version + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status IN ('SUBMITTING', 'RECONCILIATION_REQUIRED')
  AND order_request_id = #{orderRequestId}

UPDATE ticket_purchase_plan
SET status = #{status},
    fail_reason = #{failReason},
    version = version + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status IN ('SUBMITTING', 'RECONCILIATION_REQUIRED')
  AND order_request_id = #{orderRequestId}

UPDATE ticket_purchase_plan
SET status = #{status},
    fail_reason = #{failReason},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status IN ('SUBMITTING', 'RECONCILIATION_REQUIRED')
  AND order_request_id = #{orderRequestId}

UPDATE ticket_purchase_plan
SET status = #{status},
    active_plan_key = NULL,
    version = version + 1,
    fail_reason = NULL,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status IN ('DRAFT', 'READY', 'FAILED')
  AND version = #{version}

